(* :366-371 after diginet_body_check returned: the take, or the refusal. Its own lemma so that no Qed holds
   both halves of the turn. *)
Lemma tkw_bcret : forall n, tkw_join_P n ->
  forall (W2 : world segs) (mem4 : word -> option byte) (md4 : Model) (ms : machine_state)
    (B1 : list byte) (hd1 : Z) (XS : list byte) (i taken1 kept1 len1 : Z) (body1 : list byte)
    (ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
  ms_eqv (tk_at_R2 ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 GP TP (@YK11.fp_regs fx) (@YK11.fp_csr fx)
            mem4 SP' i taken1 kept1 len1 bp
            (DgnLib.body_check
               (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i))))) ms ->
  tkw_inv W2 mem4 md4 B1 hd1 XS (tk_spill bp blp hdp allow (Z_to_bv 64 taken1)) ->
  tkw_mw B1 -> (forall j, i <= j < TW.S_queued Bw -> TW.S_queue_len B1 j <= 24) ->
  0 <= i < 512 -> 0 <= taken1 -> 0 <= kept1 -> taken1 + kept1 = i -> (taken1 = 0 -> len1 = 0) ->
  0 <= len1 <= 1484 -> Z.of_nat (length body1) = len1 -> 0 <= hd1 < 256 ->
  i + 1 + Z.of_nat n = TW.S_queued Bw ->
  len1 + TW.S_queue_len B1 i <= 1484 ->
  firstn (Z.to_nat len1) XS = body1 ->
  firstn (Z.to_nat (len1 + TW.S_queue_len B1 i)) XS =
    body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i)) ->
  (DgnLib.body_check (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i))) = 0 ->
     tkw_next B1 i (taken1 + 1) kept1 (len1 + TW.S_queue_len B1 i)
       (Z.lor hd1 (TW.S_queue_display B1 i))
       (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i))) n =
     Some (BF, (body, len, hd, taken, keptF))) ->
  (DgnLib.body_check (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i))) <> 0 ->
     tkw_next (tkm_keep B1 kept1 i) i taken1 (kept1 + 1) len1 hd1 body1 n =
     Some (BF, (body, len, hd, taken, keptF))) ->
  SRr segs W2 (mkCfg ms md4) Q.
Proof.
  intros n JOIN W2 mem4 md4 ms B1 hd1 XS i taken1 kept1 len1 body1
    ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 EQR INV4 MW HQL1 Hi Ht Hk HTK HT0 HL HBL HD HFU HLC EXS0 EXS
    HOK HNO.
  pose proof HFF as (WFF & QFF & GFF & T0 & K0 & TK & QR & LR & BL & HDR & GF').
  pose proof tkw_spf as (P1 & P2 & P3 & P4 & P5 & P6 & P7 & P8).
  pose proof tkw_consts as (E1 & E2 & E3 & E4 & E5 & E6 & E7 & E8 & E9).
  pose proof tkw_addrs as (A1 & A2 & A3 & A4 & A5 & A6 & A7 & A8 & A9 & A10).
  pose proof tkw_cellf as (B0 & B63 & BM & B4 & Bce & L0 & L63 & LM & H0 & H63 & HM & OL & OH).
  pose proof asan_consts as (AC1 & AC2 & AC3 & AC4 & AC5).
  pose proof (tkw_cell_ge hdp 4 HTWH HNGH HRDH ltac:(lia)) as H4096.
  pose proof (tkw_cell_ge blp 8 HTWL HNGL HRDL ltac:(lia)) as L4096.
  pose proof tk_addrs as (TKE & _).
  unfold TW.S_queue_N in QR. unfold TS0.DIGINET_MAX_BODY_LEN in LR. unfold amem_range in BM, LM, HM.
  pose proof (tkm_field_ranges B1 i) as (QLr & QDr & MCr & MBr & QUr).
  assert (QL24 : TW.S_queue_len B1 i <= 24) by (apply HQL1; lia).
  pose proof INV4 as (ly5 & S5 & J5 & HF5 & HP5 & HMO5 & K5 & HTW5 & LW5 & FR5 & HDC5 & BLC5 & LX5 & GX5).
  assert (LS : length (TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i)))
               = Z.to_nat (TW.S_queue_len B1 i)).
  { apply TWL.length_sub; [unfold TW.A_S_queue_bytes; lia|].
    rewrite (tw_len _ _ _ HTW5). unfold TW.W_LEN, TW.A_S_queue_bytes. lia. }
  destruct (tkw_jf _ _ _ _ _ J5) as (HAR5 & _ & _ & _ & _).
  destruct (tkw_stkf _ _ _ _ _ J5) as (STKa5 & STKb5 & RFR5 & SP05 & SP635 & SPLO5 & SPCE5).
  destruct (tkw_rdt ly5 S5 W2 mem4 md4 B1 i HAR5 HTW5 Hi) as [RDT5 RGT5].
  destruct RDT5 as (E1' & E2' & E3' & E4' & E5' & E6' & E7' & E8').
  destruct RGT5 as (M1 & M2 & M3 & M4 & M5 & M6 & M7 & M8).
  assert (NFT : forall (W3 : world segs) (m2 : word -> option byte) (md2 : Model) (X2 : list byte) (w38 : word)
                  (r1 r7 z0 z1 y2 y3 z26 z27 q3 q4 q5 q6 : word) (ms2 : machine_state),
    ms_eqv (tk_at TK_NF r1 r7 (Z_to_bv 64 0) z0 z1 y2 y3 (Z_to_bv 64 0) (Z_to_bv 64 (TK_S + 32 * i)) z26 z27
              q3 q4 q5 q6 GP TP (@YK11.fp_regs fx) (@YK11.fp_csr fx) m2 SP' i taken1 kept1 len1) ms2 ->
    tkw_inv W3 m2 md2 B1 hd1 X2 (tk_spill bp blp hdp allow w38) ->
    firstn (Z.to_nat len1) X2 = body1 ->
    tkw_next (tkm_keep B1 kept1 i) i taken1 (kept1 + 1) len1 hd1 body1 n =
      Some (BF, (body, len, hd, taken, keptF)) ->
    SRr segs W3 (mkCfg ms2 md2) Q).
  { intros W3 m2 md2 X2 w38 r1 r7 z0 z1 y2 y3 z26 z27 q3 q4 q5 q6 ms2 HE INV2 HFX2 HN.
    apply (tkw_nf n JOIN W3 md2 m2 B1 hd1 X2 w38 i taken1 kept1 len1 body1 r1 r7 (Z_to_bv 64 0) z0 z1 y2 y3
             (Z_to_bv 64 0) z26 z27 q3 q4 q5 q6 ms2 HE INV2).
    - exact MW.
    - exact HQL1.
    - exact Hi.
    - lia.
    - lia.
    - exact HTK.
    - exact HT0.
    - lia.
    - exact HBL.
    - lia.
    - lia.
    - exact HFX2.
    - exact HN. }
           destruct (Z.eq_dec (DgnLib.body_check
                       (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i)))) 0)
             as [FB|FB].
           ++ (* the body check accepts: :368-371 *)
              pose proof (HOK FB) as HNX.
              rewrite FB in EQR. unfold tk_at_R2 in EQR.
              destruct (tkw_hd_sh ly5 S5 W2 mem4 md4 J5 HP5 K5) as (khd & SHD & HKD & RHD).
              assert (RDHD : ov_read_bytes rsegs mem4 (wa hdp) 4 = Some (TW.put 4 hd1)).
              { destruct HDC5 as ((_ & BH) & _). cbn [cells_bytes cbytes] in BH.
                rewrite app_nil_r, TWL.le4_put in BH. exact (tkw_ovr mem4 hdp _ 4 BH (TWL.length_put 4 hd1)). }
              eapply (tkw_run W2 _ _ mem4 ms md4 _ Q EQR).
              {                 eapply (tk_run_bc_ok (LCK.RNG_W (world segs) (@w_H segs) W2)) with (lo := sp - TAKE_STK)
                  (sv := tk_sv) (hd := hd1) (khd := khd);
                  [ exact FR5 | reflexivity | exact RFR5 | exact STKa5 | lia | lia
                  | exact E3' | exact E4' | exact E7' | exact E8' | exact SHD | exact RDHD
                  | exact M3 | exact M4 | exact M7 | exact M8 | exact RHD
                  | exact (tkw_cell_rng hdp 4 ly5 S5 W2 mem4 md4 HTWH HNGH HRDH J5 HP5)
                  | exact HDC5 | lia | exact HHD4 | exact HKD | lia | lia
                  | lia | lia | lia | lia | lia | lia | lia ]. }
              intros ms5 ms6 md5 HP5' HE5 HG5 HS5.
              destruct HP5' as (m5 & w0' & w1' & w2' & w3' & w24' & w26' & w27' & -> & MU5 & WM5 & ST5 & CH5 & FR5').
              cbn [ms_mem] in HG5.
              assert (J6 : ajx G 0 [] STK sp0 FP ly St W0 mem0 md0 own ly5 S5 W2 m5 md5 k).
              { apply (tkw_jrun ly5 S5 W2 mem4 md4 m5 md5 (fun a => hdp <= a < hdp + 4) J5 HP5).
                - intros x Hx. cbv beta in Hx. apply MU5. cbn [outside]. tauto.
                - exact HG5.
                - exact HS5.
                - intros a Ha. cbv beta in Ha. right. left. apply tkw_outs. right. exact Ha. }
              eapply (JOIN W2 md5 m5 B1 (Z.lor hd1 (TW.S_queue_display B1 i)) XS (Z_to_bv 64 taken1) i
                       (taken1 + 1) kept1 (len1 + TW.S_queue_len B1 i)
                       (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i) (Z.to_nat (TW.S_queue_len B1 i)))).
              ** exact HE5.
              ** apply (tkw_inv_mu W2 mem4 md4 m5 md5 ly5 S5 B1 (Z.lor hd1 (TW.S_queue_display B1 i)) XS
                          (tk_spill bp blp hdp allow (Z_to_bv 64 taken1)) (fun a => hdp <= a < hdp + 4)
                          J5 HF5 HP5 HMO5 K5 HTW5 LX5 GX5 BLC5 J6
                          ltac:(intros x Hx; cbv beta in Hx; apply MU5; cbn [outside]; tauto) HG5
                          ltac:(intros a Ha; cbv beta in Ha; right; exact Ha) LW5 FR5' CH5).
              ** split; [exact MW|].
                 split; [intros jj Hjj; apply HQL1; lia|].
                 split; [lia|]. split; [lia|]. split; [lia|]. split; [lia|]. split; [intros Hz; lia|].
                 split; [lia|].
                 split; [rewrite length_app, LS; lia|].
                 split; [apply tkm_lor_byte; lia|]. split; [lia|].
                 split; [exact EXS | exact HNX].
           ++ (* the body check refuses: :366 *)
              pose proof (HNO FB) as HNX.
              unfold tk_at_R2 in EQR.
              eapply (tkw_run W2 _ _ mem4 ms md4 _ Q EQR).
              {                 eapply (tk_run_bc_ne (LCK.RNG_W (world segs) (@w_H segs) W2)) with (lo := sp - TAKE_STK)
                  (sv := tk_sv);
                  [ exact FR5 | reflexivity | exact RFR5 | exact STKa5 | lia | lia
                  | lia | lia | lia | lia | exact FB
                  | destruct (tkw_bcr (body1 ++ TW.sub B1 (TW.A_S_queue_bytes i)
                                        (Z.to_nat (TW.S_queue_len B1 i)))) as [Hr|Hr]; rewrite Hr; lia ]. }
              intros ms5 ms6 md5 HP5' HE5 HG5 HS5.
              destruct HP5' as (w0' & w1' & w2' & w3' & w26' & w27' & ->).
              exact (NFT W2 mem4 md5 XS (Z_to_bv 64 taken1) _ _ w0' w1' w2' w3' w26' w27' _ _ _ _ ms6 HE5
                       (tkw_inv_run0 W2 mem4 md4 md5 B1 hd1 XS
                          (tk_spill bp blp hdp allow (Z_to_bv 64 taken1)) INV4 HS5) EXS0
                       ltac:(unfold TKK.tkw_next, tkm_keep; exact HNX)).
Qed.

End Call.
